"""Tests for the small-files compaction job."""
import shutil
import sys
from pathlib import Path

import pyarrow.parquet as pq
import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from compact import (  # noqa: E402
    TARGET_MAX_BYTES,
    TARGET_MIN_BYTES,
    compact,
)

INPUT_DIR = ROOT / "input"
OUTPUT_DIR = ROOT / "output"


def partition_files(root: Path) -> dict[str, list[Path]]:
    parts: dict[str, list[Path]] = {}
    for p in sorted(root.rglob("*.parquet")):
        rel = p.relative_to(root)
        parts.setdefault(rel.parts[0], []).append(p)
    return parts


def all_event_ids(root: Path) -> list[int]:
    ids = []
    for p in root.rglob("*.parquet"):
        ids.extend(pq.read_table(p, columns=["event_id"])["event_id"].to_pylist())
    return ids


@pytest.fixture(scope="session", autouse=True)
def generated_input():
    assert INPUT_DIR.exists(), "run gen_input.py first to create input/"
    if OUTPUT_DIR.exists():
        shutil.rmtree(OUTPUT_DIR)


@pytest.fixture(scope="session")
def compaction_result(generated_input):
    return compact(INPUT_DIR, OUTPUT_DIR)


def test_rows_and_event_ids_preserved(compaction_result):
    in_ids = sorted(all_event_ids(INPUT_DIR))
    out_ids = sorted(all_event_ids(OUTPUT_DIR))
    assert len(in_ids) == len(out_ids)
    assert in_ids == out_ids


def test_output_sizes_within_band(compaction_result):
    parts = partition_files(OUTPUT_DIR)
    assert parts, "no output produced"
    for part, files in parts.items():
        sizes = [f.stat().st_size for f in files]
        for f, size in zip(files[:-1], sizes[:-1]):
            assert TARGET_MIN_BYTES <= size <= TARGET_MAX_BYTES, (
                f"{f} ({size}B) outside band"
            )
        last_size = sizes[-1]
        assert last_size <= TARGET_MAX_BYTES, (
            f"final file of {part} exceeds cap: {last_size}B"
        )


def test_file_count_strictly_reduced(compaction_result):
    n_in = sum(len(v) for v in partition_files(INPUT_DIR).values())
    n_out = sum(len(v) for v in partition_files(OUTPUT_DIR).values())
    assert n_in >= 240, "expected the full generated input set"
    assert n_out < n_in


def test_rerun_on_output_is_noop(compaction_result, tmp_path):
    rerun_root = tmp_path / "output_rerun"
    shutil.copytree(OUTPUT_DIR, rerun_root)

    before = [
        (p.relative_to(rerun_root).as_posix(), p.stat().st_size)
        for p in sorted(rerun_root.rglob("*.parquet"))
    ]
    compact(rerun_root, rerun_root)
    after = [
        (p.relative_to(rerun_root).as_posix(), p.stat().st_size)
        for p in sorted(rerun_root.rglob("*.parquet"))
    ]

    assert len(after) == len(before)
    assert sorted(before) == sorted(after)

